import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireGlu Release Notes","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireGlu/aireglu-v1-122-0.md","filePath":"aireblock-releases/AireGlu/aireglu-v1-122-0.md","lastUpdated":1788947601000}`),a={name:`aireblock-releases/AireGlu/aireglu-v1-122-0.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireglu-release-notes" tabindex="-1"><span class="fsc-product"><img src="/aireglu-icon.png"> AireGlu Release Notes</span> <a class="header-anchor" href="#aireglu-release-notes" aria-label="Permalink to “AireGlu Release Notes”">​</a></h1><blockquote><p><strong>Version:</strong> 1.122.0<br><strong>Release Date:</strong> 9 September 2026</p></blockquote><h2 id="summary-of-changes" tabindex="-1">Summary of Changes <a class="header-anchor" href="#summary-of-changes" aria-label="Permalink to “Summary of Changes”">​</a></h2><h4 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h4><ul><li>New OIDC JWT Token Authentication Type (GLU-3223)</li></ul><h4 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h4><ul><li>Fixed Job Task Display for Long Job Names (GLU-3259)</li></ul><h4 id="🔒-security-enhancement" tabindex="-1">🔒 Security Enhancement <a class="header-anchor" href="#🔒-security-enhancement" aria-label="Permalink to “🔒 Security Enhancement”">​</a></h4><ul><li>Improved Endpoint Security Controls (GLU-3070)</li></ul><h1 id="detailed-changes" tabindex="-1">Detailed Changes <a class="header-anchor" href="#detailed-changes" aria-label="Permalink to “Detailed Changes”">​</a></h1><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><hr><h4 id="new-oidc-jwt-token-authentication-types-glu-3223" tabindex="-1">New OIDC JWT Token Authentication Types (GLU-3223) <a class="header-anchor" href="#new-oidc-jwt-token-authentication-types-glu-3223" aria-label="Permalink to “New OIDC JWT Token Authentication Types (GLU-3223)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Endpoints can now be secured with an OIDC JWT token authentication type. AireGlu validates the JWT presented on the request and only grants access if the token’s aud and scope claims match what the endpoint expects.</p></div><div class="tip custom-block"><p class="custom-block-title">What this means for you</p><p>Any endpoint can now be gated on a token the caller already holds. AireGlu checks the aud and scope claims, so you control which clients can reach the endpoint. The token is also available downstream, so the caller’s identity and permissions can be carried through to onward systems.</p></div><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><hr><h4 id="fixed-job-task-display-for-long-job-names-glu-3259" tabindex="-1">Fixed Job Task Display for Long Job Names (GLU-3259) <a class="header-anchor" href="#fixed-job-task-display-for-long-job-names-glu-3259" aria-label="Permalink to “Fixed Job Task Display for Long Job Names (GLU-3259)”">​</a></h4><div class="info custom-block"><p class="custom-block-title">Description</p><p>Jobs with long job names were rendering incorrectly on the Job Tasks screen following a previous related fix. This has been corrected so long job names now display properly without reintroducing the earlier issue.</p></div>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};